int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    int pos = 0;

    if (!from || !to || fromlen <= 0 || tolen <= 0) {
        return -EINVAL;
    }

    while (pos < fromlen) {
        if (pos + 1 > fromlen) {
            return -EINVAL;
        }

        int component_len = from[pos];
        pos++;

        if (component_len == 0) {
            break;
        }

        if (pos + component_len > fromlen) {
            return -EINVAL;
        }

        if (tolen < (to - to) + component_len + 1) {
            return -ENAMETOOLONG;
        }

        for (int i = 0; i < component_len; i++) {
            to[ret++] = from[pos++];
        }

        if (ret > 0 && to[ret - 1] == '\0') {
            return -EINVAL;
        }

        if (ret + 1 > tolen) {
            return -ENAMETOOLONG;
        }

        to[ret++] = '\0';
    }

    if (ret == 0) {
        to[0] = '\0';
        ret = 0;
    } else {
        to[ret - 1] = '\0';
    }

    return 0;
}

int path_component_to_str(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j;

    if (fromlen <= 0 || tolen <= 0)
        return -EINVAL;

    if (from == NULL || to == NULL)
        return -EFAULT;

    for (i = 0, j = 0; i < fromlen && j < tolen - 1; i++) {
        unsigned char c = from[i];

        if (c == '/') {
            if (j < tolen - 1)
                to[j++] = '/';
        } else if (c == '.') {
            if (j + 1 < tolen - 1) {
                to[j++] = '.';
                to[j++] = '.';
            } else {
                return -ENOSPC;
            }
        } else if (isalnum(c)) {
            to[j++] = c;
        } else {
            continue;
        }
    }

    if (j < tolen)
        to[j] = '\0';
    else {
        return -ENOSPC;
    }

    return 0;
}

int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;

    if (tolen <= 0 || fromlen <= 0 || from == NULL || to == NULL) {
        return -EINVAL;
    }

    while (pos < fromlen) {
        if (pos + 1 > fromlen) {
            return -EIO;
        }

        unsigned char type = from[pos];

        if (type == '\0') {
            break;
        }

        if (type == TYPE_SYMLINK) {
            if (pos + 2 > fromlen) {
                return -EIO;
            }
            int len = from[pos + 1];
            if (pos + 2 + len > fromlen) {
                return -EIO;
            }
            if (tolen <= 0) {
                return -ENAMETOOLONG;
            }
            to[tolen - 1] = '\0';
            return -ENAMETOOLONG;
        } else if (type == TYPE_DIR) {
            if (tolen <= 0) {
                return -ENAMETOOLONG;
            }
            to[0] = '/';
            tolen--;
            to++;
            pos++;
            continue;
        } else if (type == TYPE_FILE_NAME) {
            if (pos + 2 > fromlen) {
                return -EIO;
            }
            int len = from[pos + 1];
            if (pos + 2 + len > fromlen) {
                return -EIO;
            }
            if (len > tolen) {
                return -ENAMETOOLONG;
            }
            memcpy(to, from + pos + 2, len);
            to += len;
            tolen -= len;
            pos += 2 + len;
            continue;
        }

        pos++;
    }

    if (tolen > 0) {
        to[0] = '\0';
    }

    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen <= 0 || fromlen <= 0)
        return -EINVAL;

    for (i = 0; i < fromlen; i++) {
        if (j >= tolen - 1)
            return -ENAMETOOLONG;

        switch (from[i]) {
            case '\0':
                to[j++] = '\0';
                break;
            case '.': {
                if (i + 1 < fromlen && from[i + 1] == '.') {
                    if (j + 2 > tolen - 1)
                        return -ENAMETOOLONG;
                    to[j++] = '.';
                    to[j++] = '.';
                    i++; // skip the next dot
                } else {
                    to[j++] = from[i];
                }
                break;
            }
            case '/':
                // Skip or ignore slashes
                break;
            default:
                to[j++] = from[i];
                break;
        }
    }

    // Null-terminate the string
    if (j >= tolen) {
        return -ENAMETOOLONG;
    }
    to[j] = '\0';

    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;

    if (tolen <= 0 || fromlen <= 0)
        return -EINVAL;

    while (pos < fromlen) {
        int component_len = from[pos];

        if (component_len == 0)
            break;

        pos += 1;
        if (pos + component_len > fromlen)
            return -EINVAL;

        if (component_len > tolen)
            return -ENAMETOOLONG;

        for (int i = 0; i < component_len; i++) {
            *to++ = from[pos++];
            tolen--;
        }
    }

    *to = '\0';

    return 0;
}
